package lr2touch;
import java.awt.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import javax.swing.*;
/** Two-player LAN coordinator. All match state is serialized under this monitor. */
public final class BattleServer implements AutoCloseable {
 static final String VERSION="1";
 final Set<BattleWire> sessions=ConcurrentHashMap.newKeySet();final Semaphore connections=new Semaphore(8);final Peer[] peers=new Peer[2];final String pin,adminPassword;final ServerSocket listener;final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();BattleHttp http;final Path overlay;int overlayPort=-1;boolean overlayLan;
 volatile boolean closed;String round="",phase="LOBBY",message="Connect two clients",hash="",title="",artist="",table="",hold="";long deadline,roundSince;boolean checked,singlePlayer;int source=-1;
 final class Peer {BattleWire wire;int slot=-1;String name="",build="",offer="",title="",artist="",table="",hold="",manifest="",error="",notes="";boolean ready,armed,committed;int ex;long rtt=Long.MAX_VALUE,errorNs=Long.MAX_VALUE,lastSync,lastSeen=System.nanoTime(),started;int samples;}
 BattleServer(int port,int webPort,String pin,Path overlay)throws IOException{this.pin=pin;this.overlay=overlay;this.adminPassword=randomAdminPassword();listener=new ServerSocket();listener.bind(new InetSocketAddress(port));BattleWire.thread("battle-accept",()->{while(!closed)try{Socket socket=listener.accept();if(!connections.tryAcquire()){socket.close();continue;}Peer peer=new Peer();peer.wire=new BattleWire(socket,v->receive(peer,v),()->{connections.release();sessions.remove(peer.wire);disconnected(peer);});sessions.add(peer.wire);peer.wire.start();}catch(IOException e){if(!closed)message="Listener error";}});if(webPort>=0){http=new BattleHttp(webPort,overlay,this::json,this::webCommand,adminPassword,false);overlayPort=http.port();}timer.scheduleWithFixedDelay(this::tick,0,200,TimeUnit.MILLISECONDS);}
 static String randomAdminPassword(){String alphabet="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";java.security.SecureRandom random=new java.security.SecureRandom();StringBuilder value=new StringBuilder(10);for(int i=0;i<10;i++)value.append(alphabet.charAt(random.nextInt(alphabet.length())));return value.toString();}
 synchronized void receive(Peer p,String[] v){try{p.lastSeen=System.nanoTime();if(p.slot<0){if(v.length!=5||!v[0].equals("HELLO")||!v[1].equals(VERSION)||!v[2].equals(pin)){p.wire.close();return;}int slot=peers[0]==null?0:!singlePlayer&&peers[1]==null?1:-1;if(slot<0){p.wire.close();return;}p.slot=slot;p.name=BattleWire.clean(v[3]);p.build=v[4];peers[slot]=p;p.wire.send("WELCOME",""+(slot+1));message="Client "+(slot+1)+" connected";return;}
  switch(v[0]){
   case "PING":long received=System.nanoTime();p.wire.send("PONG",v[1],""+received,""+System.nanoTime());break;
   case "SYNC":p.rtt=Long.parseLong(v[1]);p.errorNs=Long.parseLong(v[2]);p.samples=Integer.parseInt(v[3]);p.lastSync=System.nanoTime();break;
   case "OFFER":if(!phase.equals("LOBBY")&&!phase.equals("FINISHED")&&!phase.equals("CANCELLED"))break;p.offer=v[1];p.title=BattleWire.clean(v[2]);p.artist=BattleWire.clean(v[3]);p.table=BattleWire.clean(v[4]);p.hold=v[5];message=p.name+" offered "+p.title;break;
   case "CHECKED":if(!matching(v)||!phase.equals("VERIFYING"))break;p.manifest=v[2];p.hold=v[3];if(all(q->!q.manifest.isEmpty())){if(!singlePlayer&&(!peers[0].manifest.equals(peers[1].manifest)||!peers[0].hold.equals(peers[1].hold))){abort("Chart folder or hold mode differs");break;}phase="LOADING";roundSince=System.nanoTime();broadcast("LOAD",round);}break;
   case "READY":if(!matching(v)||!phase.equals("LOADING"))break;p.ready=true;p.notes=v[2];if(p.slot==source){title=BattleWire.clean(v[3]);artist=BattleWire.clean(v[4]);table=BattleWire.clean(v[5]);}if(all(q->q.ready)){if(!singlePlayer&&!peers[0].notes.equals(peers[1].notes)){abort("Parsed chart note counts differ");break;}phase="READY";message=singlePlayer?"Test chart loaded. Check sync, then Start.":"Both charts loaded. Check sync, then Start.";}break;
   case "ARMED":if(!matching(v)||!phase.equals("ARMING"))break;p.armed=true;if(all(q->q.armed)&&deadline-System.nanoTime()>2_000_000_000L){phase="COUNTDOWN";broadcast("COMMIT",round);}break;
   case "COMMITTED":if(matching(v)&&phase.equals("COUNTDOWN"))p.committed=true;break;
   case "SCORE":if(!matching(v)||!(phase.equals("COUNTDOWN")||phase.equals("PLAYING")))break;p.ex=Math.max(0,Integer.parseInt(v[2]));if(p.started==0&&Long.parseLong(v[3])!=0)p.started=Long.parseLong(v[3]);if(v[4].equals("FINISHED"))p.error="FINISHED";if(all(q->q.error.equals("FINISHED"))){phase="FINISHED";message=singlePlayer?"Single player test finished":"Both players finished";}break;
   case "ERROR":if(matching(v))abort(p.name+": "+BattleWire.clean(v[2]));break;
   case "LEAVE":p.wire.close();break;
   default:throw new IOException("Unknown command");
  }
 }catch(Exception e){p.wire.close();}}
 boolean matching(String[] v){return !round.isEmpty()&&v.length>1&&round.equals(v[1]);}
 boolean participants(){return peers[0]!=null&&(singlePlayer||peers[1]!=null);}
 boolean all(java.util.function.Predicate<Peer> test){return participants()&&test.test(peers[0])&&(singlePlayer||test.test(peers[1]));}
 synchronized boolean setSinglePlayer(boolean enabled){if(!(phase.equals("LOBBY")||phase.equals("FINISHED")||phase.equals("CANCELLED"))||enabled&&peers[1]!=null){message="Finish/cancel the round and disconnect player 2 before changing mode";return false;}singlePlayer=enabled;checked=false;message=enabled?"SINGLE PLAYER TEST: connect one client; cross-player sync is not tested":"TWO PLAYER BATTLE: connect two clients";return true;}
 boolean both(){return peers[0]!=null&&peers[1]!=null;}
 boolean clockGood(Peer p){return p!=null&&p.samples>=8&&p.rtt>=0&&p.rtt<=20_000_000&&p.errorNs>=0&&p.errorNs<=10_000_000&&System.nanoTime()-p.lastSync<2_000_000_000L;}
 synchronized boolean select(int slot){if(!participants()||slot<0||slot>1||peers[slot]==null||!(phase.equals("LOBBY")||phase.equals("FINISHED")||phase.equals("CANCELLED"))){message="Connect required players and finish/cancel the previous round";return false;}Peer chosen=peers[slot];if(!chosen.offer.matches("[0-9a-fA-F]{64}")){message="That player must offer a chart first";return false;}if(!singlePlayer&&!peers[0].build.equals(peers[1].build)){message="Game builds differ; use identical beatoraja.jar files";return false;}source=slot;round=UUID.randomUUID().toString();hash=chosen.offer;title=chosen.title;artist=chosen.artist;table=chosen.table;hold=chosen.hold;checked=false;deadline=0;roundSince=System.nanoTime();for(Peer p:peers){if(p==null)continue;p.manifest="";p.ready=p.armed=p.committed=false;p.error="";p.notes="";p.started=0;p.ex=0;}phase="VERIFYING";message="Checking local chart and folder hashes";broadcast("CHECK",round,hash,hold);return true;}
 synchronized boolean checkSync(){checked=all(this::clockGood);message=checked?"Clock check passed (estimated error <=10 ms per client)":"Waiting for stable clocks: use wired LAN if possible";return checked;}
 synchronized boolean startRound(){if(!phase.equals("READY")||!checked||!all(this::clockGood)){message="Required charts must be ready and clocks checked";return false;}deadline=System.nanoTime()+5_000_000_000L;phase="ARMING";message="Scheduling shared start";broadcast("ARM",round,""+deadline);return true;}
 synchronized void abort(String reason){if(round.isEmpty()){message=reason;return;}phase="CANCELLED";checked=false;deadline=0;message=reason;broadcast("ABORT",round,reason);}
 synchronized void disconnected(Peer p){if(p.slot>=0&&peers[p.slot]==p){peers[p.slot]=null;abort("Player "+(p.slot+1)+" disconnected; round invalid");}}
 void broadcast(String... v){for(Peer p:peers)if(p!=null)p.wire.send(v);}
 synchronized void tick(){if(closed)return;try{long now=System.nanoTime();for(Peer p:peers)if(p!=null&&now-p.lastSeen>5_000_000_000L)p.wire.close();if((phase.equals("VERIFYING")||phase.equals("LOADING"))&&now-roundSince>180_000_000_000L)abort("Preparation timed out");if((phase.equals("ARMING")||phase.equals("COUNTDOWN"))&&deadline-now<1_000_000_000L&&(!all(q->q.committed)))abort("Start acknowledgement missing");if(phase.equals("COUNTDOWN")&&now>=deadline){phase="PLAYING";message=singlePlayer?"Single player test running (no opponent sync measurement)":"Battle running";}if(phase.equals("PLAYING")&&now-deadline>3_000_000_000L&&(!all(q->q.started!=0)))abort("A client did not report its start; round invalid");broadcast("STATE",phase,message,peers[0]==null?"":peers[0].name,peers[1]==null?"":peers[1].name);if(phase.equals("PLAYING")&&both()&&peers[0].started!=0&&peers[1].started!=0){long skew=Math.abs(peers[0].started-peers[1].started);message=String.format(Locale.ROOT,"Software start skew: %.2f ms%s",skew/1e6,skew>40_000_000?" · CHECK AUDIO / NETWORK":"");}}catch(Exception e){abort("Coordinator error");}}
 synchronized String json(){StringBuilder b=new StringBuilder("{");b.append("\"singlePlayer\":").append(singlePlayer).append(",\"phase\":").append(BattleWire.json(phase)).append(",\"message\":").append(BattleWire.json(message)).append(",\"title\":").append(BattleWire.json(title)).append(",\"artist\":").append(BattleWire.json(artist)).append(",\"table\":").append(BattleWire.json(table)).append(",\"players\":[");for(int i=0;i<2;i++){if(i>0)b.append(',');Peer p=peers[i];b.append("{\"name\":").append(BattleWire.json(p==null?(singlePlayer&&i==1?"Not used in single player test":"Waiting for player"):p.name)).append(",\"ex\":").append(p==null?0:p.ex).append(",\"connected\":").append(p!=null).append('}');}return b.append("],\"difference\":").append((peers[0]==null?0:peers[0].ex)-(peers[1]==null?0:peers[1].ex)).append('}').toString();}
 synchronized boolean webCommand(String action){switch(action){case "status":return true;case "p1":return select(0);case "p2":return select(1);case "sync":return checkSync();case "start":return startRound();case "cancel":if(round.isEmpty()){message="No active round to cancel";return false;}abort("Cancelled by host from browser");return true;case "mode":return setSinglePlayer(!singlePlayer);default:return false;}}
 public synchronized void close(){closed=true;timer.shutdownNow();try{listener.close();}catch(Exception e){}for(BattleWire session:sessions)session.close();sessions.clear();if(http!=null)http.close();}
 static JButton button(String text,Runnable action){JButton b=new JButton(text){protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(getModel().isPressed()?new Color(0x36536A):new Color(0x24394D));g.fillRoundRect(0,0,getWidth(),getHeight(),14,14);g.dispose();super.paintComponent(graphics);}};b.setContentAreaFilled(false);b.setBorderPainted(false);b.setFocusPainted(false);b.setForeground(new Color(0xEAF0F8));b.setFont(new Font("Dialog",0,22));b.setPreferredSize(new Dimension(240,64));b.addActionListener(e->action.run());return b;}
 void window(){JFrame f=new JFrame("LR2oraja LAN Battle Server");f.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);JPanel body=new JPanel(new BorderLayout(16,16));body.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));body.setBackground(new Color(0x142231));JTextArea info=new JTextArea();info.setEditable(false);info.setLineWrap(true);info.setWrapStyleWord(true);info.setFont(new Font("Dialog",0,22));info.setForeground(new Color(0xEAF0F8));info.setBackground(body.getBackground());body.add(new JScrollPane(info));JButton mode=button("MODE: TWO PLAYER BATTLE",()->setSinglePlayer(!singlePlayer));JButton remote=button("WEB CONTROL: LOCAL ONLY",()->confirmOverlayLan(f));JPanel top=new JPanel(new GridLayout(1,2,10,0));top.setOpaque(false);top.add(mode);top.add(remote);body.add(top,BorderLayout.NORTH);JPanel controls=new JPanel(new GridLayout(2,3,10,10));controls.add(button("Use player 1 chart",()->select(0)));controls.add(button("Use player 2 chart",()->select(1)));controls.add(button("Check sync",this::checkSync));controls.add(button("START BATTLE",this::startRound));controls.add(button("Cancel round",()->{if(JOptionPane.showConfirmDialog(f,"Cancel this round?","Cancel",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)abort("Cancelled by host");}));controls.add(button("OBS ELEMENT URLS / COPY",()->obsElements(f)));body.add(controls,BorderLayout.SOUTH);f.setContentPane(body);f.setSize(1120,760);f.setLocationRelativeTo(null);f.setVisible(true);javax.swing.Timer refresh=new javax.swing.Timer(200,e->{synchronized(this){mode.setText(singlePlayer?"MODE: SINGLE PLAYER TEST (TAP TO CHANGE)":"MODE: TWO PLAYER BATTLE (TAP TO CHANGE)");remote.setText(overlayLan?"WEB CONTROL: LAN ENABLED (TAP TO DISABLE)":"WEB CONTROL: LOCAL ONLY (TAP TO SHARE)");StringBuilder text=new StringBuilder("LAN PORT: "+listener.getLocalPort()+"    ROOM CODE: "+pin+"\nHOST IP: "+addresses()+"\nOBS: http://"+overlayHost()+":"+(http==null?"OFF":http.port())+"/\nBROWSER CONTROL: http://"+lanAddress()+":"+(http==null?"OFF":http.port())+"/control.html\nADMIN LOGIN: admin / "+adminPassword+"\n\n"+phase+" — "+message+"\n\n"+title+"\n"+artist+"\n"+table+"\n\n");for(int i=0;i<2;i++){Peer p=peers[i];text.append("PLAYER "+(i+1)+": "+(p==null?(singlePlayer&&i==1?"Not required (single player test)":"Waiting"):"CONNECTED · "+p.name+"    EX: "+p.ex+"\nOffered: "+p.title+"\nRTT: "+(p.rtt==Long.MAX_VALUE?"measuring":String.format(Locale.ROOT,"%.2f ms",p.rtt/1e6))+"    Loaded: "+p.ready)).append("\n\n");}if(both())text.append("EX DIFFERENCE (P1 - P2): "+(peers[0].ex-peers[1].ex));info.setText(text.toString());}});refresh.getActionListeners()[0].actionPerformed(null);refresh.start();f.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){refresh.stop();close();}});}

 synchronized boolean setOverlayLan(boolean enabled){if(http==null||enabled==overlayLan)return http!=null;boolean prior=overlayLan;http.close();try{http=new BattleHttp(overlayPort,overlay,this::json,this::webCommand,adminPassword,enabled);overlayLan=enabled;message=enabled?"Browser controls and OBS feed available to trusted LAN; admin login required":"Web controls and OBS feed restricted to this PC";return true;}catch(IOException e){try{http=new BattleHttp(overlayPort,overlay,this::json,this::webCommand,adminPassword,prior);}catch(IOException ignored){http=null;}message="Could not change web access: "+e.getMessage();return false;}}
 String overlayHost(){return overlayLan?lanAddress():"127.0.0.1";}
 static String lanAddress(){try{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))if(n.isUp()&&!n.isLoopback())for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress())return a.getHostAddress();}catch(Exception ignored){}return addresses().split(" / ",2)[0];}
 boolean confirmOverlayLan(JFrame owner){if(overlayLan)return setOverlayLan(false);int answer=JOptionPane.showConfirmDialog(owner,"This enables the browser control page and OBS feed for devices on your LAN. Admin actions require the generated admin password shown in this server window. Player names, scores and song information are visible on the LAN. Enable only on a trusted private network.","Enable LAN web access?",JOptionPane.YES_NO_OPTION);return answer==JOptionPane.YES_OPTION&&setOverlayLan(true);}
 void obsElements(JFrame owner){String[] labels={"Song title","Artist","Player 1 name","Player 1 score","Player 2 name","Player 2 score","Score difference"};String[] paths={"title.html","artist.html","player1-name.html","player1-score.html","player2-name.html","player2-score.html","score-difference.html"};JPanel panel=new JPanel(new GridLayout(labels.length,3,8,8));for(int i=0;i<labels.length;i++){String url="http://"+overlayHost()+":"+http.port()+"/"+paths[i];panel.add(new JLabel(labels[i]));panel.add(new JLabel(url));JButton[] copy={null};copy[0]=button("COPY",()->{try{Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new java.awt.datatransfer.StringSelection(url),null);copy[0].setText("COPIED");}catch(Exception ex){JOptionPane.showMessageDialog(owner,"Copy failed. URL: "+url);}});panel.add(copy[0]);}JOptionPane.showMessageDialog(owner,new JScrollPane(panel),"OBS transparent elements",JOptionPane.PLAIN_MESSAGE);}
 static String cachedAddresses;static String addresses(){if(cachedAddresses!=null)return cachedAddresses;try{ArrayList<String> addresses=new ArrayList<>();for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))if(n.isUp()&&!n.isLoopback())for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address)addresses.add(a.getHostAddress());return cachedAddresses=String.join(" / ",addresses);}catch(Exception e){return "Check Windows network settings";}}
 public static void main(String[] args)throws Exception{int port=args.length>0?Integer.parseInt(args[0]):24880,web=args.length>1?Integer.parseInt(args[1]):24881;String code=args.length>2?args[2]:String.format("%06d",new java.security.SecureRandom().nextInt(1000000));Path base=Paths.get(BattleServer.class.getProtectionDomain().getCodeSource().getLocation().toURI()).getParent();if(!code.matches("[0-9]{6}"))throw new IllegalArgumentException("Room code must be six digits");BattleServer s=new BattleServer(port,web,code,base.resolve("battle-overlay"));SwingUtilities.invokeLater(s::window);}
}
